<?php else:?><div class="form-grid"><?php foreach(['namaPerusahaan'=>'Nama Perusahaan','emailPerusahaan'=>'Email Perusahaan','bidangUsaha'=>'Bidang Usaha','kontak'=>'Nomor Kontak','website'=>'Website'] as $k=>$label):?><label><?= e($label) ?><input type="<?= $k==='website'?'url':($k==='emailPerusahaan'?'email':'text') ?>" name="<?= e($k) ?>" value="<?= e($profil[$k]) ?>" maxlength="<?= $k==='website'?250:($k==='kontak'?30:100) ?>"<?= in_array($k,['namaPerusahaan','emailPerusahaan'],true)?' required':'' ?>></label><?php endforeach;?></div><label>Alamat<textarea name="alamat" maxlength="2000" required><?= e($profil['alamat']) ?></textarea></label><label>Deskripsi Perusahaan<textarea name="deskripsi" maxlength="5000" rows="5"><?= e($profil['deskripsi']) ?></textarea></label><?php endif;?><div class="form-footer"><button class="button">Simpan Perubahan <?= icon('check') ?></button></div></form><?php endif;?></section>
<aside class="stack"><?php if($currentUser['role']==='Rekruter'):?><section class="card"><h2>Status verifikasi</h2><?= badge($profil['statusVerifikasi']) ?><p class="muted"><?= e($profil['catatanVerifikasi']?:'Admin akan memeriksa legalitas perusahaan.') ?></p></section><section class="card"><h2>Legalitas Perusahaan</h2><?php foreach($legalitas as $d):?><div class="history-item"><a target="_blank" rel="noopener" href="<?= e(url('dokumen/lihat',['id'=>$d['idDokumen']])) ?>"><?= e($d['namaDokumen']) ?> ↗</a><p><?= badge($d['hasilPemeriksaan']) ?></p><small><?= e($d['catatan']) ?></small></div><?php endforeach;?><form method="post" enctype="multipart/form-data" action="<?= e(url('profil/legalitas')) ?>"><?= csrf() ?><label>Jenis Dokumen<select name="namaDokumen"><option>NIB</option><option>Akta Pendirian</option><option>Izin Usaha</option></select></label><label>Berkas PDF<input type="file" name="legalitas" accept="application/pdf,.pdf" required></label><small class="muted">Maksimal 5 MB. Mengunggah ulang dokumen mengembalikan status ke Menunggu sampai diperiksa admin.</small><button class="button secondary full">Unggah Legalitas</button></form></section><?php else:?><section class="card accent-card"><?= icon('shield') ?><h2>Profil yang siap melangkah</h2><p>Profil mahasiswa digunakan pada setiap lamaran. Simpan CV di sini agar dapat digunakan kembali saat mendaftar.</p></section><?php endif;?></aside></div>
